    ($(C)!1!-90:(O)$) coordinate (OC)
    (intersection of A--OA and C--OC) coordinate (M)
    (intersection of B--OB and C--OC) coordinate (N);
\end{scope}
\draw (A)--(M)--(N)--(B)--cycle (B) arc (0:180:r);
\foreach \t/\g in {A/180,B/0,O/-90,M/180,N/0,C/goc}{
  \draw[fill=white] (\t) circle (1pt) node[shift={(\g:7pt)},font=\scriptsize]{$\t$};
}

\path (0,0) coordinate (O) (120:r) coordinate (A) (45:r) coordinate (B)
  (-30:r) coordinate (C) (210:r) coordinate (D);
\draw (A)--(B)--(C)--(D)--cycle (O) circle (r);
\foreach \t/\g in {A/120,B/45,C/-30,D/210,O/-90}{
  \draw[fill=white] (\t) circle (1pt) node[shift={(\g:9pt)},font=\scriptsize]{$\t$};
}

\path (0,0) coordinate (O) (-90:r) coordinate (M) (75:r) coordinate (N)
  (25:r) coordinate (P) (155:r) coordinate (Q);
\begin{scope}[overlay]
  \path ($(M)!1!-90:(O)$) coordinate (AB) ($(N)!1!-90:(O)$) coordinate (CD)
    ($(P)!1!-90:(O)$) coordinate (BC) ($(Q)!1!-90:(O)$) coordinate (AD)
    (intersection of AB--M and Q--AD) coordinate (A)
    (intersection of AB--M and P--BC) coordinate (B)
    (intersection of CD--N and Q--AD) coordinate (D)
    (intersection of CD--N and P--BC) coordinate (C);
\end{scope}
\draw (A)--(B)--(C)--(D)--cycle (O) circle (r);
\foreach \t/\g in {A/-90,B/-90,C/0,D/180,O/-90}{
  \draw[fill=white] (\t) circle (1pt) node[shift={(\g:9pt)},font=\scriptsize]{$\t$};
}

\path (0,0) coordinate (O) (gocm:r) coordinate (A)
  ({180-goch}:r) coordinate (B) (goch:r) coordinate (C);
\begin{scope}[overlay]
  \path ($(A)!1!-90:(O)$) coordinate (OA)
    (intersection of A--OA and B--C) coordinate (S);
\end{scope}
\path pic[draw,angle radius=5pt]{right angle=O--A--S};
\draw (O)--(A)--(S)--(B)
  let \p1=($(O)-(A)$) in (O) circle ({veclen(\x1,\y1)});
\foreach \t/\g in {A/gocm,B/{180-goch},C/goch,S/0,O/135}{
  \draw[fill=white] (\t) circle (1pt) node[shift={(\g:7pt)},font=\scriptsize]{$\t$};
}

\path (0,0) coordinate (O) (d,0) coordinate (O')
  (goc:R) coordinate (A) (-goc:R) coordinate (B)
  (goch:R) coordinate (C) (-goch:R) coordinate (D)
  ($(d,0)+(goc:r)$) coordinate (A') ($(d,0)+(-goc:r)$) coordinate (B')
  (intersection of A--A' and B--B') coordinate (S);
\foreach \x/\y/\z in {O/A/S,O/B/S}{
  \path pic[draw,angle radius=5pt]{right angle=\x--\y--\z};
}
\draw (O) circle (R) (O') circle (r) (A)--(S)--(B)--(O)--cycle;
\foreach \t/\g in {A/goc,A'/goc,B/-goc,B'/-goc,O/180,O'/-90,S/0}{
  \path[draw,fill=white] (\t) circle (1pt) node[shift={(\g:7pt)},font=\scriptsize]{$\t$};
}

\path (0,0) coordinate (O) (d,0) coordinate (O')
  (goc:R) coordinate (A) (-goc:R) coordinate (B)
  (goch:R) coordinate (C) (-goch:R) coordinate (D)
  ($(d,0)+(goc:r)$) coordinate (A') ($(d,0)+(-goc:r)$) coordinate (B')
  (intersection of A--A' and B--B') coordinate (S);
\draw (O) circle (R) (O') circle (r) (A)--(S)--(B);
\foreach \t/\g in {A/goc,A'/goc,B/-goc,B'/-goc,O/-90,O'/-90,S/0}{
  \path[draw,fill=white] (\t) circle (1pt) node[shift={(\g:7pt)},font=\scriptsize]{$\t$};
}

\path (0,0) coordinate (O) (d,0) coordinate (O') (0:R) coordinate (A);
\draw (O) circle (R) (O') circle (r);
\foreach \t/\g in {O/180,O'/-90,A/0}{
  \path[draw,fill=white] (\t) circle (1pt) node[shift={(\g:7pt)},font=\scriptsize]{$\t$};
}
